=== full Makefile ===
CC := gcc
CFLAGS := -std=c23 -Wall -Wextra -Werror -g -O1 -Iinclude -Isrc -Itests

SRC := src/rbtree.c src/pool.c
TSRC := tests/test_rbtree.c tests/fault_alloc.c tests/sweep.c tests/test_pool.c tests/test_bigstack.c
BIN := build/test_rbtree
FUZZBIN := build/fuzz

all: $(BIN) $(FUZZBIN)

$(BIN): $(SRC) $(TSRC) include/rbtree.h src/pool.h tests/fault_alloc.h tests/sweep.h tests/test_pool.h tests/test_bigstack.h
	@mkdir -p build
	$(CC) $(CFLAGS) $(SRC) $(TSRC) -o $@ -lpthread

$(FUZZBIN): $(SRC) tests/fuzz.c tests/fault_alloc.c include/rbtree.h src/pool.h tests/fault_alloc.h
	@mkdir -p build
	$(CC) $(CFLAGS) $(SRC) tests/fuzz.c tests/fault_alloc.c -o $@ -lpthread

test: $(BIN) $(FUZZBIN)
	./$(BIN) && ./$(BIN) --pooled && ./$(FUZZBIN) 100000 && ./$(FUZZBIN) 100000 --pooled

asan: CFLAGS += -fsanitize=address,undefined -fno-omit-frame-pointer
asan: clean test

# --nodes 20000: valgrind is far too slow for the 10^6-node stack test, so it
# runs smaller here. test and asan run the full 10^6. (Spec 8.3: say so.)
memcheck: all
	valgrind --leak-check=full --show-leak-kinds=all \
	--error-exitcode=1 ./$(BIN) --nodes 20000
	valgrind --leak-check=full --show-leak-kinds=all \
	--error-exitcode=1 ./$(BIN) --pooled --nodes 20000
	valgrind --leak-check=full --show-leak-kinds=all \
	--error-exitcode=1 ./$(FUZZBIN) 20000
	valgrind --leak-check=full --show-leak-kinds=all \
	--error-exitcode=1 ./$(FUZZBIN) 20000 --pooled

clean:
	rm -rf build

.PHONY: all test asan memcheck clean

=== test harness idiom (top of test_pool.c) ===
#include "test_pool.h"
#include "pool.h"
#include "fault_alloc.h"

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* Defined in tests/fault_alloc.c; not in any header on purpose. */
size_t rb_debug_live_allocs(void);

/* The node is 48 bytes today; the pool never sees its type, only this size. */
enum { OBJ = 48, MAX_LIVE = 1500 };

static int pool_failures;

#define POOL_CHECK(cond, ...)                                           \
    do {                                                                \
        if (!(cond)) {                                                  \
            pool_failures++;                                            \
            fprintf(stderr, "  pool FAIL line %d: ", __LINE__);         \
            fprintf(stderr, __VA_ARGS__);                               \
            fprintf(stderr, "\n");                                      \
        }                                                               \
    } while (0)

/* live is what the test expects; the rest is the spec's invariant plus the
 * pool's own walk of its free list. */
static void check_pool(const rb_pool_t *p, size_t want_live, const char *when)
{
    size_t slabs, live, free_objs;
    pool_stats(p, &slabs, &live, &free_objs);
    POOL_CHECK(live == want_live, "%s: live %zu, expected %zu", when, live, want_live);
    POOL_CHECK(live + free_objs == slabs * pool_objs_per_slab(p),
               "%s: live %zu + free_objs %zu != %zu slabs * %zu per slab",
               when, live, free_objs, slabs, pool_objs_per_slab(p));
    int c = pool_check(p);
    POOL_CHECK(c == 0, "%s: pool_check returned %d", when, c);
}

/* A tag at both ends of an object. If two live objects ever share a slot,
 * the second one's tag overwrites the first's and check_tag fails. */
static void put_tag(void *obj, size_t id)
{
    size_t back = ~id;

